/// `EmotionChip.after_damage_received` — accumulate HP loss into the
/// per-instance counter so the next player turn-start can detect "took
/// HP loss last turn". Mirrors Python `EmotionChip._took_damage` flag,
/// but tracked as an i32 sum (presence of any positive damage is what
/// matters at consume-time).
pub(crate) fn on_after_damage_received_emotion_chip(
    state: &mut CombatState,
    ctx: &crate::hooks::DamageCtx,
    damage: i32,
) -> EffectResult {
    if !player_owns_relic(state, crate::RelicKind::EmotionChip) {
        return EffectResult::NotImplemented;
    }
    if !matches!(ctx.target, crate::hooks::CreatureRef::Player) {
        return EffectResult::NotImplemented;
    }
    if damage <= 0 {
        return EffectResult::NotImplemented;
    }
    if let Some(r) = state
        .relics
        .iter_mut()
        .find(|r| !r.is_melted && r.kind == crate::RelicKind::EmotionChip)
    {
        r.counter = r.counter.saturating_add(damage);
    }
    EffectResult::Resolved
}

/// `EmotionChip.after_side_turn_start` — on player turn start, if the
/// counter is positive (HP loss observed during the previous turn),
/// fire every orb's passive once and zero the counter. Mirrors Python
/// `EmotionChip.after_side_turn_start` (`rare.py::EmotionChip`,
/// pool=DEFECT, hook channel `after_side_turn_start`).
pub(crate) fn on_after_side_turn_start_emotion_chip(
    state: &mut CombatState,
    side: Side,
) -> EffectResult {
    if side != Side::Player {
        return EffectResult::NotImplemented;
    }
    if !player_owns_relic(state, crate::RelicKind::EmotionChip) {
        return EffectResult::NotImplemented;
    }
    let triggered = {
        let r = state
            .relics
            .iter_mut()
            .find(|r| !r.is_melted && r.kind == crate::RelicKind::EmotionChip);
        match r {
            Some(r) if r.counter > 0 => {
                r.counter = 0;
                true
            }
            _ => false,
        }
    };
    if !triggered {
        return EffectResult::NotImplemented;
    }
    trigger_every_orb_passive(state);
    EffectResult::Resolved
}

/// EmotionChip orb walk: each channeled orb's passive, in queue order.
///
/// v0.111.0 `EmotionChip.AfterPlayerTurnStart` passes
/// `countAffectedByHooks: true` (decomp `EmotionChip.cs:54`), which routes
/// `OrbCmd.Passive` through the new `OrbModel.TriggerPassive`
/// (`OrbModel.cs:246-261`):
///
/// [decompiled C# omitted — see the cited path]
///
/// The only `ModifyOrbPassiveTriggerCount` listener is GoldPlatedCables:
/// `+1` for `OrbQueue.Orbs[0]` (`GoldPlatedCables.cs`). v0.107.1 called
/// `orb.Passive` directly, so Cables never doubled an EmotionChip trigger.
///
/// Every orb kind fires, Plasma's `+1 energy` included — `PlasmaOrb.Passive`
/// is `GainEnergy(PassiveVal)` in both builds (v0.107.1 `EmotionChip.cs:52-56`
/// calls `OrbCmd.Passive` on every orb). The turn-end
/// [`crate::orbs::passive_tick`] skips Plasma, so it can't be reused here
/// (GH #806).
fn trigger_every_orb_passive(state: &mut CombatState) {
    let filled: smallvec::SmallVec<[usize; 10]> = state
        .player
        .orbs
        .slots
        .iter()
        .enumerate()
        .filter(|(_, o)| !o.is_empty())
        .map(|(i, _)| i)
        .collect();
    let cables = state.game_version >= crate::GameVersion::V0_111_0
        && player_owns_relic(state, crate::RelicKind::GoldPlatedCables);
    for (n, idx) in filled.into_iter().enumerate() {
        let count = if n == 0 && cables { 2 } else { 1 };
        for _ in 0..count {
            crate::orbs::trigger_orb_passive_at(state, idx);
        }
    }
}

/// `EmotionChip.after_combat_end` — clear the HP-loss counter so it
/// doesn't carry across combats.
